import java.math.BigDecimal
import java.math.RoundingMode

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    init {
        // Initialize with zero balances using proper scale
    }

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (balances.containsKey(id)) {
            throw IllegalArgumentException("Account $id already exists")
        }
        // Validate initial amount is non-negative
        if (initial < BigDecimal.ZERO) {
            throw IllegalArgumentException("Initial amount must be non-negative")
        }
        // Set scale to 2 decimal places
        val scaledInitial = initial.setScale(2, RoundingMode.HALF_UP)
        balances[id] = scaledInitial
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal {
        val bal = balances[id] ?: throw NoSuchElementException("Account $id not found")
        return bal.setScale(2, RoundingMode.HALF_UP)
    }

    fun transfer(from: String, to: String, amount: BigDecimal) {
        // Validate amount is positive
        if (amount <= BigDecimal.ZERO) {
            throw IllegalArgumentException("Amount must be positive")
        }
        // Set scale to 2 decimal places
        val scaledAmount = amount.setScale(2, RoundingMode.HALF_UP)

        // Check if accounts exist
        if (!balances.containsKey(from)) {
            throw NoSuchElementException("Account $from not found")
        }
        if (!balances.containsKey(to)) {
            throw NoSuchElementException("Account $to not found")
        }

        val fromBalance = balances[from]!!
        val toBalance = balances[to]!!

        // Check if transfer would overdraw
        if (fromBalance < scaledAmount) {
            throw IllegalStateException("insufficient funds")
        }

        // Perform the transfer atomically
        val newFromBalance = fromBalance - scaledAmount
        val newToBalance = toBalance + scaledAmount

        balances[from] = newFromBalance
        balances[to] = newToBalance

        log[from]!!.add(-scaledAmount)
        log[to]!!.add(scaledAmount)
    }

    fun history(id: String): List<BigDecimal> {
        val entries = log[id] ?: throw NoSuchElementException("Account $id not found")
        return entries.map { it.setScale(2, RoundingMode.HALF_UP) }
    }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            if (n <= 0) {
                throw IllegalArgumentException("n must be positive")
            }
            if (total < BigDecimal.ZERO) {
                throw IllegalArgumentException("Total must be non-negative")
            }

            // Divide total by n, rounding down to 2 decimal places
            val part = total.divide(BigDecimal(n), 2, RoundingMode.DOWN)
            val remainder = total - part * BigDecimal(n)

            // Create list with larger parts first
            // remainder is the leftover cents to distribute
            // We need to add 0.01 to 'remainder' number of parts
            val remainderCents = remainder.setScale(0, RoundingMode.HALF_UP).toLong()

            val result = mutableListOf<BigDecimal>()
            for (i in 0 until n) {
                if (i < remainderCents) {
                    result.add(part + BigDecimal("0.01"))
                } else {
                    result.add(part)
                }
            }

            return result
        }
    }
