fun toJson(value: Any?, indent: Int = 0): String {
    val sb = StringBuilder()
    writeValue(value, sb, indent, 0)
    return sb.toString()
}

private fun writeValue(value: Any?, sb: StringBuilder, indent: Int, level: Int) {
    when (value) {
        null -> sb.append("null")
        is Boolean -> sb.append(if (value) "true" else "false")
        is String -> writeString(value, sb)
        is Int -> sb.append(value)
        is Long -> sb.append(value)
        is Double -> writeDouble(value, sb)
        is Float -> writeDouble(value.toDouble(), sb)
        is Map<*, *> -> writeMap(value, sb, indent, level)
        is List<*> -> writeList(value, sb, indent, level)
        is Array<*> -> writeList(value.toList(), sb, indent, level)
        is Enum<*> -> sb.append("\"").append(value.name).append("\"")
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.java.name}")
    }
}

private fun writeString(value: String, sb: StringBuilder) {
    sb.append('"')
    for (i in value.indices) {
        val c = value[i]
        when (c) {
            '"' -> sb.append("\\\"")
            '\\' -> sb.append("\\\\")
            '\b' -> sb.append("\\b")
            '\f' -> sb.append("\\f")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            else -> {
                if (c < 0x20) {
                    sb.append("\\u00")
                    sb.append(hexDigit((c.code shr 4) and 0xF))
                    sb.append(hexDigit(c.code and 0xF))
                } else {
                    sb.append(c)
                }
            }
        }
    }
    sb.append('"')
}

private fun hexDigit(n: Int): Char {
    return if (n < 10) ('0' + n) else ('a' + n - 10)
}

private fun writeDouble(value: Double, sb: StringBuilder) {
    if (value.isNaN() || value.isInfinite()) {
        throw IllegalArgumentException("Non-finite double value: $value")
    }
    sb.append(value.toString())
}

private fun writeMap(value: Map<*, *>, sb: StringBuilder, indent: Int, level: Int) {
    if (indent == 0) {
        writeCompactMap(value, sb)
    } else {
        writePrettyMap(value, sb, indent, level)
    }
}

private fun writeCompactMap(value: Map<*, *>, sb: StringBuilder) {
    sb.append('{')
    var first = true
    for ((key, v) in value) {
        if (key !is String) {
            throw IllegalArgumentException("Map key must be String, got: ${key::class.java.name}")
        }
        if (!first) {
            sb.append(',')
        }
        first = false
        writeString(key, sb)
        sb.append(':')
        writeValue(v, sb, 0, 0)
    }
    sb.append('}')
}

private fun writePrettyMap(value: Map<*, *>, sb: StringBuilder, indent: Int, level: Int) {
    sb.append('{')
    if (value.isEmpty()) {
        sb.append('}')
        return
    }
    sb.append('\n')
    val nextLevel = level + 1
    val nextIndent = " ".repeat(nextLevel * indent)
    val currentIndent = " ".repeat(level * indent)
    var first = true
    for ((key, v) in value) {
        if (key !is String) {
            throw IllegalArgumentException("Map key must be String, got: ${key::class.java.name}")
        }
        if (!first) {
            sb.append(',')
            sb.append('\n')
        }
        first = false
        sb.append(nextIndent)
        writeString(key, sb)
        sb.append(": ")
        writeValue(v, sb, indent, nextLevel)
    }
    sb.append('\n')
    sb.append(currentIndent)
    sb.append('}')
}

private fun writeList(value: List<*>, sb: StringBuilder, indent: Int, level: Int) {
    if (indent == 0) {
        writeCompactList(value, sb)
    } else {
        writePrettyList(value, sb, indent, level)
    }
}

private fun writeCompactList(value: List<*>, sb: StringBuilder) {
    sb.append('[')
    var first = true
    for (v in value) {
        if (!first) {
            sb.append(',')
        }
        first = false
        writeValue(v, sb, 0, 0)
    }
    sb.append(']')
}

private fun writePrettyList(value: List<*>, sb: StringBuilder, indent: Int, level: Int) {
    sb.append('[')
    if (value.isEmpty()) {
        sb.append(']')
        return
    }
    sb.append('\n')
    val nextLevel = level + 1
    val nextIndent = " ".repeat(nextLevel * indent)
    val currentIndent = " ".repeat(level * indent)
    var first = true
    for (v in value) {
        if (!first) {
            sb.append(',')
            sb.append('\n')
        }
        first = false
        sb.append(nextIndent)
        writeValue(v, sb, indent, nextLevel)
    }
    sb.append('\n')
    sb.append(currentIndent)
    sb.append(']')
}
