```kotlin
sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}
class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val len = input.length

    // Track what kind of token we just saw to validate '-'
    var lastTokenType: TokenType? = null

    enum class TokenType {
        IDENT, STR, NUM, OP, PAREN
    }

    while (i < len) {
        val ch = input[i]

        // Skip whitespace
        if (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r') {
            i++
            continue
        }

        val startPos = i

        // Check for identifiers, numbers, or strings
        if (ch.isLetter() || ch == '_') {
            // Identifier
            var j = i
            while (j < len && (input[j].isLetterOrDigit() || input[j] == '_' || input[j] == '.')) {
                // Dots are only allowed after the first character
                if (input[j] == '.' && j == i) {
                    throw TokenizeException("Invalid character '.' at start of identifier", j)
                }
                j++
            }
            val name = input.substring(i, j)
            tokens.add(Token.Ident(name, startPos))
            lastTokenType = TokenType.IDENT
            i = j
        } else if (ch.isDigit()) {
            // Number
            var j = i
            while (j < len && input[j].isDigit()) {
                j++
            }
            if (j < len && input[j] == '.') {
                // Check for 5. case: digit followed by dot, then no more digits
                val afterDot = j + 1
                if (afterDot >= len || !input[afterDot].isDigit()) {
                    throw TokenizeException("Malformed number", i)
                }
                j = afterDot
                while (j < len && input[j].isDigit()) {
                    j++
                }
            }
            val numStr = input.substring(i, j)
            val value = numStr.toDouble()
            tokens.add(Token.Num(value, startPos))
            lastTokenType = TokenType.NUM
            i = j
        } else if (ch == '-' && (lastTokenType == null || lastTokenType == TokenType.OP || lastTokenType == TokenType.PAREN)) {
            // Negative number
            var j = i + 1
            if (j >= len || !input[j].isDigit()) {
                throw TokenizeException("Invalid character '-'", i)
            }
            while (j < len && input[j].isDigit()) {
                j++
            }
            if (j < len && input[j] == '.') {
                val afterDot = j + 1
                if (afterDot >= len || !input[afterDot].isDigit()) {
                    throw TokenizeException("Malformed number", i)
                }
                j = afterDot
                while (j < len && input[j].isDigit()) {
                    j++
                }
            }
            val numStr = input.substring(i, j)
            val value = numStr.toDouble()
            tokens.add(Token.Num(value, startPos))
            lastTokenType = TokenType.NUM
            i = j
        } else if (ch == '"' || ch == '\'') {
            // String
            val quoteChar = ch
            var j = i + 1
            val sb = StringBuilder()
            while (j < len) {
                val c = input[j]
                if (c == '\\') {
                    if (j + 1 >= len) {
                        throw TokenizeException("Unterminated string", i)
                    }
                    val nextChar = input[j + 1]
                    when (nextChar) {
                        'n' -> sb.append('\n')
                        't' -> sb.append('\t')
                        'r' -> sb.append('\r')
                        '\\' -> sb.append('\\')
                        quoteChar -> sb.append(quoteChar)
                        else -> sb.append(nextChar)
                    }
                    j += 2
                } else if (c == quoteChar) {
                    j++
                    break
                } else {
                    sb.append(c)
                    j++
                }
            }
            if (j >= len && input.last() != quoteChar && (j - 1 < 0 || input[j - 1] != quoteChar)) {
                // Check if we broke out because of end of string or end of input
                // If j == len, we didn't find the closing quote
                if (j >= len) {
                    throw TokenizeException("Unterminated string", i)
                }
            }
            tokens.add(Token.Str(sb.toString(), startPos))
            lastTokenType = TokenType.STR
            i = j
        } else if (ch == '(') {
            tokens.add(Token.Paren(true, startPos))
            lastTokenType = TokenType.PAREN
            i++
        } else if (ch == ')') {
            tokens.add(Token.Paren(false, startPos))
            lastTokenType = TokenType.PAREN
            i++
        } else {
            // Operators: longest match first
            val opCandidates = listOf("==", "!=", "<=", ">=", "<", ">", "&&", "||", "!")
            var matched = false
            for (op in opCandidates) {
                if (input.startsWith(op, i)) {
                    tokens.add(Token.Op(op, startPos))
                    lastTokenType = TokenType.OP
                    i += op.length
                    matched = true
                    break
                }
            }
            if (!matched) {
                throw TokenizeException("Unexpected character '$ch'", i)
            }
        }
    }

    return tokens
}
