def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    """
    Evaluate a small expression language.

    Grammar (lowest to highest precedence):
    1. Conditional: a ? b : c (right-associative)
    2. Logical OR: ||
    3. Logical AND: &&
    4. Comparisons: == != < <= > >= (non-associative)
    5. Addition/Subtraction: + - (left-associative)
    6. Multiplication/Division/Modulo: * / % (left-associative)
    7. Unary: - + ! (right-associative in terms of binding, but unary operators bind tightest after power)
    8. Power: ^ (right-associative)
    9. Atoms: literals, identifiers, function calls, parentheses
    """
    if env is None:
        env = {}

    # Tokenizer
    tokens = tokenize(expr)

    # Parser
    parser = Parser(tokens, env)
    result = parser.parse_expression()

    # Check for trailing tokens
    if parser.pos < len(parser.tokens):
        raise SyntaxError(f"Unexpected token: {parser.tokens[parser.pos]}")

    return result


class Token:
    def __init__(self, type_: str, value: str, pos: int):
        self.type = type_
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.type}, {self.value!r})"


def tokenize(expr: str) -> list[Token]:
    """Tokenize the expression string."""
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]

        # Skip whitespace
        if c in ' \t\n\r':
            i += 1
            continue

        # Two-character operators
        if i + 1 < n:
            two = expr[i:i+2]
            if two == '||':
                tokens.append(Token('OP', '||', i))
                i += 2
                continue
            elif two == '&&':
                tokens.append(Token('OP', '&&', i))
                i += 2
                continue
            elif two == '==':
                tokens.append(Token('OP', '==', i))
                i += 2
                continue
            elif two == '!=':
                tokens.append(Token('OP', '!=', i))
                i += 2
                continue
            elif two == '<=':
                tokens.append(Token('OP', '<=', i))
                i += 2
                continue
            elif two == '>=':
                tokens.append(Token('OP', '>=', i))
                i += 2
                continue

        # Single-character operators
        if c in '+-*/%^=!<>?:()':
            tokens.append(Token('OP', c, i))
            i += 1
            continue

        # Numbers: integer or decimal
        if c.isdigit() or c == '.':
            start = i
            has_dot = False
            if c == '.':
                has_dot = True
                i += 1
                if i >= n or not expr[i].isdigit():
                    raise SyntaxError(f"Invalid number at position {i}")
            while i < n and (expr[i].isdigit() or (expr[i] == '.' and not has_dot)):
                if expr[i] == '.':
                    has_dot = True
                i += 1
            num_str = expr[start:i]
            if has_dot:
                tokens.append(Token('NUMBER', float(num_str), start))
            else:
                tokens.append(Token('NUMBER', int(num_str), start))
            continue

        # Identifiers
        if c.isalpha() or c == '_':
            start = i
            while i < n and (expr[i].isalnum() or expr[i] == '_'):
                i += 1
            name = expr[start:i]
            tokens.append(Token('IDENT', name, start))
            continue

        raise SyntaxError(f"Unexpected character '{c}' at position {i}")

    return tokens


class Parser:
    def __init__(self, tokens: list[Token], env: dict[str, float]):
        self.tokens = tokens
        self.pos = 0
        self.env = env

    def current(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def peek(self) -> Token | None:
        return self.current()

    def advance(self) -> Token:
        tok = self.current()
        if tok is None:
            raise SyntaxError("Unexpected end of input")
        self.pos += 1
        return tok

    def expect(self, type_: str, value: str | None = None) -> Token:
        tok = self.current()
        if tok is None:
            raise SyntaxError(f"Expected {type_} but got end of input")
        if tok.type != type_:
            raise SyntaxError(f"Expected {type_} but got {tok.type} ({tok.value!r})")
        if value is not None and tok.value != value:
            raise SyntaxError(f"Expected {value!r} but got {tok.value!r}")
        return self.advance()

    def parse_expression(self) -> int | float:
        """Parse the entire expression (lowest precedence: conditional)."""
        return self.parse_conditional()

    def parse_conditional(self) -> int | float:
        """Parse conditional expression: a ? b : c (right-associative)."""
        left = self.parse_logical_or()

        if self.current() is not None and self.current().value == '?':
            self.advance()  # consume '?'
            true_branch = self.parse_conditional()  # right-associative
            self.expect('OP', ':')
            false_branch = self.parse_conditional()  # right-associative

            if left != 0:
                return true_branch
            else:
                return false_branch

        return left

    def parse_logical_or(self) -> int | float:
        """Parse logical OR: || (short-circuit)."""
        left = self.parse_logical_and()

        while self.current() is not None and self.current().value == '||':
            self.advance()  # consume '||'
            # Short-circuit: if left is non-zero, skip right side
            if left != 0:
                # We still need to parse the right side to consume tokens, but we don't evaluate it
                # Actually, we need to parse it to ensure correct token consumption
                # But for short-circuit, we should not evaluate the right side
                # Let's parse it but ignore the result
                right = self.parse_logical_and()
                left = 1
            else:
                right = self.parse_logical_and()
                if right != 0:
                    left = 1
                else:
                    left = 0

        return left

    def parse_logical_and(self) -> int | float:
        """Parse logical AND: && (short-circuit)."""
        left = self.parse_comparison()

        while self.current() is not None and self.current().value == '&&':
            self.advance()  # consume '&&'
            # Short-circuit: if left is zero, skip right side
            if left == 0:
                right = self.parse_comparison()
                left = 0
            else:
                right = self.parse_comparison()
                if right != 0:
                    left = 1
                else:
                    left = 0

        return left

    def parse_comparison(self) -> int | float:
        """Parse comparison operators: == != < <= > >= (non-associative)."""
        left = self.parse_additive()

        if self.current() is not None and self.current().type == 'OP' and self.current().value in ('==', '!=', '<', '<=', '>', '>='):
            op = self.advance().value
            right = self.parse_additive()

            if op == '==':
                result = 1 if left == right else 0
            elif op == '!=':
                result = 1 if left != right else 0
            elif op == '<':
                result = 1 if left < right else 0
            elif op == '<=':
                result = 1 if left <= right else 0
            elif op == '>':
                result = 1 if left > right else 0
            elif op == '>=':
                result = 1 if left >= right else 0
            else:
                raise SyntaxError(f"Unknown comparison operator: {op}")

            return result

        return left

    def parse_additive(self) -> int | float:
        """Parse addition and subtraction: + - (left-associative)."""
        left = self.parse_multiplicative()

        while self.current() is not None and self.current().type == 'OP' and self.current().value in ('+', '-'):
            op = self.advance().value
            right = self.parse_multiplicative()

            if op == '+':
                left = left + right
            elif op == '-':
                left = left - right

        return left

    def parse_multiplicative(self) -> int | float:
        """Parse multiplication, division, and modulo: * / % (left-associative)."""
        left = self.parse_unary()

        while self.current() is not None and self.current().type == 'OP' and self.current().value in ('*', '/', '%'):
            op = self.advance().value
            right = self.parse_unary()

            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                # If both are ints and division is exact, return int
                if isinstance(left, int) and isinstance(right, int) and left % right == 0:
                    left = left // right
                else:
                    left = left / right
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError("Modulo by zero")
                left = left % right

        return left

    def parse_unary(self) -> int | float:
        """Parse unary operators: - + ! (right-associative in binding)."""
        if self.current() is not None and self.current().type == 'OP' and self.current().value in ('-', '+', '!'):
            op = self.advance().value
            operand = self.parse_unary()  # right-associative

            if op == '-':
                return -operand
            elif op == '+':
                return +operand
            elif op == '!':
                return 1 if operand == 0 else 0

        return self.parse_power()

    def parse_power(self) -> int | float:
        """Parse power operator: ^ (right-associative)."""
        base = self.parse_atom()

        if self.current() is not None and self.current().type == 'OP' and self.current().value == '^':
            self.advance()  # consume '^'
            exponent = self.parse_power()  # right-associative
            return base ** exponent

        return base

    def parse_atom(self) -> int | float:
        """Parse atoms: literals, identifiers, function calls, parentheses."""
        tok = self.current()

        if tok is None:
            raise SyntaxError("Unexpected end of input")

        # Number literal
        if tok.type == 'NUMBER':
            self.advance()
            return tok.value

        # Identifier
        if tok.type == 'IDENT':
            name = tok.value
            self.advance()

            # Check for function call
            if self.current() is not None and self.current().value == '(':
                return self.parse_function_call(name)

            # Variable lookup
            if name not in self.env:
                raise NameError(f"Undefined variable: {name}")
            return self.env[name]

        # Parenthesized expression
        if tok.value == '(':
            self.advance()  # consume '('
            result = self.parse_expression()
            self.expect('OP', ')')
            return result

        # If we get here, it's an error
        raise SyntaxError(f"Unexpected token: {tok}")

    def parse_function_call(self, name: str) -> int | float:
        """Parse a function call: name(args)."""
        self.expect('OP', '(')

        args = []

        # Parse first argument
        if self.current() is not None and self.current().value != ')':
            args.append(self.parse_expression())

        # Parse remaining arguments
        while self.current() is not None and self.current().value == ',':
            self.advance()  # consume ','
            if self.current() is None or self.current().value == ')':
                raise SyntaxError("Trailing comma in function call")
            args.append(self.parse_expression())

        self.expect('OP', ')')

        # Validate function name and argument count
        if name == 'min':
            if len(args) < 1:
                raise SyntaxError("min() requires at least 1 argument")
            return min(args)
        elif name == 'max':
            if len(args) < 1:
                raise SyntaxError("max() requires at least 1 argument")
            return max(args)
        elif name == 'abs':
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        else:
            raise NameError(f"Undefined function: {name}")
