        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(self.prerelease)
        if self.build:
            s += "+" + self.build
        return s

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch, self.prerelease) == (other.major, other.minor, other.patch, other.prerelease)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, tuple(self.prerelease)))

    def _cmp_key(self) -> Tuple:
        """Key for comparison, ignoring build metadata."""
        # Prelease: None (release) is greater than any prerelease list
        # For prerelease lists: compare element by element
        # Numeric identifiers are compared as integers, alphanumeric as strings
        # A shorter list is smaller if all preceding elements are equal

        def prerelease_key(pre):
            if pre is None:
                # Release is greater than any prerelease
                return (1,)
            else:
                # Prerelease is less than release
                # We need to make this comparable with tuples
                # Return (0, ...) where ... is the comparison key for the prerelease list
                items = []
                for ident in pre:
                    if ident.isdigit():
                        items.append((0, int(ident), ""))
                    else:
                        items.append((1, 0, ident))
                return (0, items)

        return (self.major, self.minor, self.patch, prerelease_key(self.prerelease))

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() < other._cmp_key()

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() <= other._cmp_key()

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() > other._cmp_key()

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() >= other._cmp_key()


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 version string."""
    if not isinstance(v, str):
        raise ValueError(f"Invalid version: {v}")

    # Strip leading 'v' or '='
    s = v.strip()
    if s.startswith('v') or s.startswith('V'):
        s = s[1:]
    if s.startswith('='):
        s = s[1:]
    s = s.strip()

    if not s:
        raise ValueError(f"Invalid version: {v}")

    # SemVer regex
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    # No leading zeros in numeric parts
    # Prerelease identifiers: [0-9A-Za-z-]+, non-empty
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

    m = re.match(pattern, s)
    if not m:
        raise ValueError(f"Invalid version: {v}")

    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    prerelease_str = m.group(4)
    build_str = m.group(5)

    prerelease = None
    if prerelease_str is not None:
