    # Handle X-ranges: replace x, X, * with 0
    # But we need to be careful about what's being replaced
    # Split by dots
    parts = s.split('.')

    # Check for invalid characters in numeric parts
    # We'll validate each part

    def validate_and_convert(part: str) -> int:
        """Convert a version part to int, handling x/X/* as 0."""
        if part.lower() == 'x' or part == '*':
            return 0
        if not part.isdigit():
            raise ValueError(f"Invalid version part: {part}")
        # Check for leading zeros
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Leading zero in version part: {part}")
        return int(part)

    if len(parts) == 1:
        major = validate_and_convert(parts[0])
        minor = 0
        patch = 0
    elif len(parts) == 2:
        major = validate_and_convert(parts[0])
        minor = validate_and_convert(parts[1])
        patch = 0
    elif len(parts) == 3:
        major = validate_and_convert(parts[0])
        minor = validate_and_convert(parts[1])
        patch = validate_and_convert(parts[2])
    else:
        raise ValueError(f"Invalid version: {s}")

    return Version(major, minor, patch)


