    """Check if version satisfies a single comparator."""
    if comparator == '<':
        return version < target
    elif comparator == '<=':
        return version <= target
    elif comparator == '>':
        return version > target
    elif comparator == '>=':
        return version >= target
    elif comparator == '=' or comparator == '':
        return version == target
    else:
        raise ValueError(f"Invalid comparator: {comparator}")


