    A prerelease version only satisfies a set if some comparator in that set has a version with the
    same MAJOR.MINOR.PATCH and a prerelease.
    """
    if not _is_prerelease(version):
        return True

    # Check if any comparator has a version with the same MAJOR.MINOR.PATCH and a prerelease
    has_matching_prerelease_comparator = False
    for comp_op, comp_ver in comparators:
        if _has_same_major_minor_patch(version, comp_ver) and _is_prerelease(comp_ver):
            has_matching_prerelease_comparator = True
            break

    if not has_matching_prerelease_comparator:
        return False

    # Must still satisfy all comparators
    for comp_op, comp_ver in comparators:
        if not _satisfies_single(version, comp_op, comp_ver):
