    """Check if version satisfies a set of comparators."""
    if not comparators:
        return True

    # If version is a prerelease, special rules apply
    if _is_prerelease(version):
        return _prerelease_satisfies_set(version, comparators)

    # For non-prerelease versions, just check all comparators
    for comp_op, comp_ver in comparators:
        if not _satisfies_single(version, comp_op, comp_ver):
            return False

    return True


