    """Parse a comparator set (whitespace-separated comparators)."""
    s = s.strip()
    if not s or s == '*':
        return []

    comparators = []
    # Split by whitespace
    parts = s.split()

    for part in parts:
        # Parse comparator and version
        # Comparator can be <, <=, >, >=, =, or empty
        m = re.match(r'^(<=|>=|<|>|=)?(.+)$', part)
        if not m:
            raise ValueError(f"Invalid comparator: {part}")

        op = m.group(1) if m.group(1) else ''
        ver_str = m.group(2).strip()

        if not ver_str:
            raise ValueError(f"Invalid comparator: {part}")

        target = _version_from_partial(ver_str)
        comparators.append((op, target))

    return comparators


def _parse_range(s: str) -> List[List[Tuple[str, Version]]]:
    """Parse a range string into a list of comparator sets."""
    s = s.strip()
    if not s:
        raise ValueError("Empty range")

    # Split by ||
    sets_str = s.split('||')
    sets = []

    for set_str in sets_str:
        set_str = set_str.strip()
        if not set_str or set_str == '*':
            sets.append([])
        else:
            comparators = _parse_comparator_set(set_str)
            sets.append(comparators)

    return sets


def _satisfies_range(version: Version, rng: str) -> bool:
    """Check if version satisfies a range."""
    sets = _parse_range(rng)

    for comparators in sets:
        if _satisfies_set(version, comparators):
