    Returns (lower, upper) where lower is inclusive and upper is exclusive.
    Returns None if the set is empty (matches everything).
    """
    if not comparators:
        return None

    # Check for special cases
    # If any comparator is just '*', it matches everything, but we need to check all comparators
    # Actually, '*' in a set means the set matches everything only if it's the only thing
    # But we already handle empty sets and '*' as matching everything

    # For now, let's handle the common cases
    # We need to find the effective lower and upper bounds

    lower = None
    upper = None
    lower_inclusive = True
    upper_inclusive = False

    for op, ver in comparators:
        if op == '<':
            if upper is None or ver < upper or (ver == upper and not upper_inclusive):
                upper = ver
                upper_inclusive = False
        elif op == '<=':
            if upper is None or ver < upper or (ver == upper and not upper_inclusive):
                upper = ver
                upper_inclusive = True
        elif op == '>':
            if lower is None or ver > lower or (ver == lower and not lower_inclusive):
