    """Find the maximum version in the list that satisfies the range."""
    if not versions:
        return None

    parsed_versions = []
    for v_str in versions:
        try:
            v = parse(v_str)
            parsed_versions.append((v_str, v))
        except ValueError:
            # Skip invalid versions? Or raise?
            # The problem says "return the original string", so we should only consider valid versions
            # But if all are invalid, return None
            pass

    if not parsed_versions:
        return None

    # Filter versions that satisfy the range
    satisfying = []
    for v_str, v in parsed_versions:
        if _satisfies_range(v, rng):
            satisfying.append((v_str, v))

    if not satisfying:
        return None

    # Find the maximum
    max_v = max(satisfying, key=lambda x: x[1])
