            sets.append(comparators)

    return sets


def _satisfies_range(version: Version, rng: str) -> bool:
    """Check if version satisfies a range."""
    sets = _parse_range(rng)

    for comparators in sets:
        if _satisfies_set(version, comparators):
            return True

    return False


def satisfies(version: str, rng: str) -> bool:
    """Check if a version satisfies a range."""
    v = parse(version)
    return _satisfies_range(v, rng)


def _expand_comparator_set(comparators: List[Tuple[str, Version]]) -> Optional[Tuple[Version, Version]]:
    """
    Expand a comparator set into a lower and upper bound.
    Returns (lower, upper) where lower is inclusive and upper is exclusive.
    Returns None if the set is empty (matches everything).
    """
    if not comparators:
        return None

    lower = None
    upper = None
    lower_inclusive = True
    upper_inclusive = False

    for op, ver in comparators:
        if op == '<':
            if upper is None or ver < upper or (ver == upper and not upper_inclusive):
                upper = ver
                upper_inclusive = False
        elif op == '<=':
            if upper is None or ver < upper or (ver == upper and not upper_inclusive):
                upper = ver
                upper_inclusive = True
        elif op == '>':
            if lower is None or ver > lower or (ver == lower and not lower_inclusive):
                lower = ver
                lower_inclusive = False
        elif op == '>=':
            if lower is None or ver > lower or (ver == lower and not lower_inclusive):
                lower = ver
                lower_inclusive = True
        elif op == '=' or op == '':
            # Exact match
            if lower is None or ver > lower or (ver == lower and not lower_inclusive):
                lower = ver
                lower_inclusive = True
            if upper is None or ver < upper or (ver == upper and not upper_inclusive):
                upper = ver
                upper_inclusive = True

    if lower is None:
        return None

    return (lower, upper, lower_inclusive, upper_inclusive)


def _version_to_str(v: Version) -> str:
    """Convert a Version to a string."""
    s = f"{v.major}.{v.minor}.{v.patch}"
    if v.prerelease:
        s += "-" + ".".join(v.prerelease)
    if v.build:
        s += "+" + v.build
    return s


def max_satisfying(versions: list, rng: str) -> Optional[str]:
    """Find the maximum version in the list that satisfies the range."""
    if not versions:
        return None

    parsed_versions = []
    for v_str in versions:
        try:
            v = parse(v_str)
            parsed_versions.append((v_str, v))
        except ValueError:
            # Skip invalid versions
            pass

    if not parsed_versions:
        return None

    # Filter versions that satisfy the range
    satisfying = []
    for v_str, v in parsed_versions:
        if _satisfies_range(v, rng):
            satisfying.append((v_str, v))

    if not satisfying:
        return None

    # Find the maximum
    max_v = max(satisfying, key=lambda x: x[1])
    return max_v[0]
