def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Implement a subset of POSIX shell word splitting and parameter expansion.

    Args:
        line: The command line string to parse.
        env: The environment variables dictionary.

    Returns:
        A list of words after parsing, splitting, and expansion.

    Raises:
        ValueError: For unterminated quotes, unterminated ${, or trailing backslash.
    """

    def expand_unquoted(text: str, env: dict[str, str]) -> str:
        """Expand parameter references in an unquoted text."""
        result = []
        i = 0
        n = len(text)

        while i < n:
            if text[i] == '$':
                # Check for ${ or $NAME
                if i + 1 < n and text[i + 1] == '{':
                    # ${...} expansion
                    j = i + 2
                    # Find the closing }
                    depth = 1
                    while j < n and depth > 0:
                        if text[j] == '{':
                            depth += 1
                        elif text[j] == '}':
                            depth -= 1
                        j += 1

                    if depth != 0:
                        raise ValueError("Unterminated ${")

                    # Extract the content between ${ and }
                    content = text[i + 2:j - 1]

                    # Parse the content to determine the type of expansion
                    # Find the variable name
                    name_end = 0
                    while name_end < len(content) and (content[name_end].isalnum() or content[name_end] == '_'):
                        name_end += 1

                    if name_end == 0:
                        # Invalid variable name, treat as literal
                        result.append('${' + content + '}')
                    else:
                        name = content[:name_end]
                        rest = content[name_end:]

                        if rest.startswith(':-'):
                            # ${NAME:-default}
                            # The default extends to the closing }
                            # We need to find the end of the default within the content
                            # The default is everything after :- until the end of content
                            default = rest[2:]
                            # The default text itself undergoes $ expansion
                            expanded_default = expand_unquoted(default, env)
                            value = env.get(name, '')
                            if value == '':
                                result.append(expanded_default)
                            else:
                                result.append(value)
                        elif rest.startswith('-'):
                            # ${NAME-default}
                            default = rest[1:]
                            expanded_default = expand_unquoted(default, env)
                            value = env.get(name, '')
                            if name not in env:
                                result.append(expanded_default)
                            else:
                                result.append(value)
                        else:
                            # Simple ${NAME}
                            value = env.get(name, '')
                            result.append(value)
                    i = j
                    continue
                else:
                    # $NAME expansion
                    j = i + 1
                    while j < n and (text[j].isalnum() or text[j] == '_'):
                        j += 1

                    if j == i + 1:
                        # $ not followed by a valid name character
                        # Check if it's followed by {
                        if j < n and text[j] == '{':
                            # This is ${...}, handled above
                            pass
                        else:
                            # Literal $
                            result.append('$')
                            i += 1
                            continue

                    name = text[i + 1:j]
                    value = env.get(name, '')
                    result.append(value)
                    i = j
                    continue
            else:
                result.append(text[i])
                i += 1

        return ''.join(result)

    words = []
    i = 0
    n = len(line)

    current_word_parts = []  # List of (text, is_quoted) tuples
    in_single_quote = False
    in_double_quote = False

    def finalize_current_word():
        """Finalize the current word."""
        if not current_word_parts:
            return

        # Build the expanded string for the current word
        expanded_parts = []
        had_unquoted_expansion = False

        for text, is_quoted in current_word_parts:
            if is_quoted:
                expanded_parts.append(text)
            else:
                expanded_text = expand_unquoted(text, env)
                expanded_parts.append(expanded_text)
                had_unquoted_expansion = True

        expanded_word = ''.join(expanded_parts)

        # Check if the word has any quoted parts
        has_quoted = any(is_quoted for _, is_quoted in current_word_parts)

        if had_unquoted_expansion:
            if has_quoted:
                # No splitting, add as-is
                words.append(expanded_word)
            else:
                # Split on whitespace
                parts = expanded_word.split()
                for part in parts:
                    if part:
                        words.append(part)
                # If parts is empty, the word is removed
        else:
            # No unquoted expansion, no splitting
            if has_quoted:
                words.append(expanded_word)
            else:
                # Empty word with no quoted parts is removed
                if expanded_word:
                    words.append(expanded_word)

    while i < n:
        c = line[i]

        if in_single_quote:
            if c == "'":
                in_single_quote = False
                i += 1
            else:
                current_word_parts.append((c, True))
                i += 1
        elif in_double_quote:
            if c == '"':
                in_double_quote = False
                i += 1
            elif c == '\\':
                if i + 1 < n:
                    next_c = line[i + 1]
                    if next_c in ('$', '"', '\\', '\n'):
                        # Escape the next character
                        if next_c == '\n':
                            # Backslash-newline is removed
                            i += 2
                        else:
                            current_word_parts.append((next_c, True))
                            i += 2
                    else:
                        # Other backslash stays as is
                        current_word_parts.append((c, True))
                        i += 1
                else:
                    raise ValueError("Trailing backslash in double quotes")
            else:
                current_word_parts.append((c, True))
                i += 1
        else:
            # Not in quotes
            if c == "'":
                in_single_quote = True
                i += 1
            elif c == '"':
                in_double_quote = True
                i += 1
            elif c in (' ', '\t', '\n'):
                # Word separator
                if current_word_parts:
                    finalize_current_word()
                    current_word_parts = []
                i += 1
            elif c == '\\':
                if i + 1 < n:
                    next_c = line[i + 1]
                    if next_c == '\n':
                        # Backslash-newline is removed
                        i += 2
                    else:
                        # Escape the next character
                        current_word_parts.append((next_c, False))
                        i += 2
                else:
                    raise ValueError("Trailing backslash")
            else:
                current_word_parts.append((c, False))
                i += 1

    # Handle unterminated quotes
    if in_single_quote:
        raise ValueError("Unterminated single quote")
    if in_double_quote:
        raise ValueError("Unterminated double quote")

    # Finalize the last word
    if current_word_parts:
        finalize_current_word()

    return words
