from __future__ import annotations

import dataclasses
import typing
from typing import Any, get_type_hints, get_origin, get_args, Union, Optional, Literal, List, Dict, Tuple

try:
    from types import UnionType  # Python 3.10+
except ImportError:
    UnionType = None


class LoadError(ValueError):
    """Error raised during loading of a dataclass from data."""
    def __init__(self, path: str, message: str):
        self.path = path
        self.message = message
        super().__init__(f"{path}: {message}")

    def __str__(self):
        return f"{self.path}: {self.message}"


def _get_type_hints_safe(cls: type) -> dict[str, Any]:
    """Get type hints for a dataclass, handling string annotations."""
    try:
        return get_type_hints(cls, include_extras=True)
    except Exception:
        # Fallback: try to get hints without resolving forward refs
        hints = {}
        for field in dataclasses.fields(cls):
            hints[field.name] = field.type
        return hints


def _is_union_type(tp: Any) -> bool:
    """Check if a type is a Union type (including Optional)."""
    origin = get_origin(tp)
    if origin is Union:
        return True
    if UnionType is not None and isinstance(tp, UnionType):
        return True
    return False


def _get_union_args(tp: Any) -> tuple:
    """Get the arguments of a Union type."""
    origin = get_origin(tp)
    if origin is Union:
        return get_args(tp)
    if UnionType is not None and isinstance(tp, UnionType):
        return get_args(tp)
    return ()


def _is_literal(tp: Any) -> bool:
    """Check if a type is a Literal type."""
    return get_origin(tp) is Literal


def _get_literal_values(tp: Any) -> tuple:
    """Get the literal values from a Literal type."""
    return get_args(tp)


def _is_optional(tp: Any) -> bool:
    """Check if a type is Optional[T] (Union[T, None])."""
    if not _is_union_type(tp):
        return False
    args = _get_union_args(tp)
    if len(args) == 2 and type(None) in args:
        return True
    return False


def _get_optional_inner(tp: Any) -> Any:
    """Get the inner type of Optional[T]."""
    args = _get_union_args(tp)
    for arg in args:
        if arg is not type(None):
            return arg
    raise ValueError("Optional must have exactly one non-None type")


def _is_list(tp: Any) -> bool:
    """Check if a type is List[T] or list[T]."""
    origin = get_origin(tp)
    return origin is list or origin is List


def _get_list_item_type(tp: Any) -> Any:
    """Get the item type of a List type."""
    args = get_args(tp)
    if args:
        return args[0]
    return Any


def _is_dict(tp: Any) -> bool:
    """Check if a type is Dict[K, V] or dict[K, V]."""
    origin = get_origin(tp)
    return origin is dict or origin is Dict


def _get_dict_key_type(tp: Any) -> Any:
    """Get the key type of a Dict type."""
    args = get_args(tp)
    if len(args) >= 1:
        return args[0]
    return Any


def _get_dict_value_type(tp: Any) -> Any:
    """Get the value type of a Dict type."""
    args = get_args(tp)
    if len(args) >= 2:
        return args[1]
    return Any


def _is_tuple(tp: Any) -> bool:
    """Check if a type is Tuple."""
    origin = get_origin(tp)
    return origin is tuple


def _is_tuple_variadic(tp: Any) -> bool:
    """Check if a tuple is variadic (Tuple[T, ...])."""
    args = get_args(tp)
    if len(args) == 2 and args[1] is Ellipsis:
        return True
    return False


def _get_tuple_item_type(tp: Any) -> Any:
    """Get the item type of a variadic Tuple[T, ...]."""
    args = get_args(tp)
    if len(args) >= 1:
        return args[0]
    return Any


def _is_tuple_fixed(tp: Any) -> bool:
    """Check if a tuple is fixed length (not variadic)."""
    return _is_tuple(tp) and not _is_tuple_variadic(tp)


def _get_tuple_fixed_types(tp: Any) -> tuple:
    """Get the types for a fixed-length tuple."""
    return get_args(tp)


def _is_dataclass(tp: Any) -> bool:
    """Check if a type is a dataclass."""
    return dataclasses.is_dataclass(tp) and not isinstance(tp, type)


def _is_primitive(tp: Any) -> bool:
    """Check if a type is a primitive type (int, float, str, bool, None)."""
    return tp in (int, float, str, bool, type(None))


def _validate_type(value: Any, expected_type: Any, path: str) -> Any:
    """Validate and convert a value to the expected type."""
    # Handle None
    if expected_type is type(None):
        if value is None:
            return None
        raise LoadError(path, f"expected None, got {type(value).__name__}")

    # Handle Literal
    if _is_literal(expected_type):
        literal_values = _get_literal_values(expected_type)
        # Check if value matches one of the literal values
        for lv in literal_values:
            if value == lv and type(value) is type(lv):
                return value
        raise LoadError(path, f"expected one of {literal_values}, got {value!r}")

    # Handle Union types (including Optional)
    if _is_union_type(expected_type):
        args = _get_union_args(expected_type)
        # Try each type in order
        errors = []
        for arg in args:
            try:
                return _validate_type(value, arg, path)
            except LoadError as e:
                errors.append(e)
        # If we get here, none of the union members matched
        # For Optional[T], if value is not None, report the error from T
        # For other unions, report the first error or a generic message
        if len(errors) > 0:
            # Report the first error's path and message
            raise errors[0]
        raise LoadError(path, f"could not match any union member")

    # Handle dataclasses
    if _is_dataclass(expected_type):
        if not isinstance(value, dict):
            raise LoadError(path, f"expected dict for dataclass, got {type(value).__name__}")
        return load(expected_type, value, path)

    # Handle list
    if _is_list(expected_type):
        if not isinstance(value, list):
            raise LoadError(path, f"expected list, got {type(value).__name__}")
        item_type = _get_list_item_type(expected_type)
        result = []
        for i, item in enumerate(value):
            item_path = f"{path}[{i}]"
            result.append(_validate_type(item, item_type, item_path))
        return result

    # Handle dict
    if _is_dict(expected_type):
        if not isinstance(value, dict):
            raise LoadError(path, f"expected dict, got {type(value).__name__}")
        key_type = _get_dict_key_type(expected_type)
        value_type = _get_dict_value_type(expected_type)
        result = {}
        for k, v in value.items():
            # Keys must be strings for JSON-like data
            if not isinstance(k, str):
                raise LoadError(path, f"expected string key, got {type(k).__name__}")
            key_path = f"{path}.{k}"
            result[k] = _validate_type(v, value_type, key_path)
        return result

    # Handle tuple
    if _is_tuple(expected_type):
        if not isinstance(value, list):
            raise LoadError(path, f"expected list for tuple, got {type(value).__name__}")
        if _is_tuple_variadic(expected_type):
            item_type = _get_tuple_item_type(expected_type)
            result = []
            for i, item in enumerate(value):
                item_path = f"{path}[{i}]"
                result.append(_validate_type(item, item_type, item_path))
            return tuple(result)
        else:
            # Fixed-length tuple
            fixed_types = _get_tuple_fixed_types(expected_type)
            if len(value) != len(fixed_types):
                raise LoadError(path, f"expected tuple of length {len(fixed_types)}, got {len(value)}")
            result = []
            for i, (item, item_type) in enumerate(zip(value, fixed_types)):
                item_path = f"{path}[{i}]"
                result.append(_validate_type(item, item_type, item_path))
            return tuple(result)

    # Handle primitives
    if expected_type is int:
        if isinstance(value, bool):
            raise LoadError(path, f"expected int, got bool (bool is not accepted for int)")
        if isinstance(value, int):
            return value
        raise LoadError(path, f"expected int, got {type(value).__name__}")

    if expected_type is float:
        if isinstance(value, bool):
            raise LoadError(path, f"expected float, got bool (bool is not accepted for float)")
        if isinstance(value, (int, float)):
            return float(value)
        raise LoadError(path, f"expected float, got {type(value).__name__}")

    if expected_type is str:
        if isinstance(value, str):
            return value
        raise LoadError(path, f"expected str, got {type(value).__name__}")

    if expected_type is bool:
        if isinstance(value, bool):
            return value
        raise LoadError(path, f"expected bool, got {type(value).__name__}")

    # Fallback: just return the value
    return value


def load(cls: type, data: Any, path: str = "$") -> Any:
    """
    Build an instance of a dataclass type `cls` from JSON-like `data`.

    Args:
        cls: The dataclass type to instantiate.
        data: The JSON-like data (dict, list, str, int, float, bool, None).
        path: The current path in the data structure (for error reporting).

    Returns:
        An instance of the dataclass.

    Raises:
        LoadError: If the data does not match the expected type.
    """
    if not dataclasses.is_dataclass(cls):
        raise ValueError(f"{cls} is not a dataclass")

    # Get type hints
    try:
        hints = get_type_hints(cls, include_extras=True)
    except Exception:
        hints = {}
        for field in dataclasses.fields(cls):
            hints[field.name] = field.type

    if not isinstance(data, dict):
        raise LoadError(path, f"expected dict for dataclass {cls.__name__}, got {type(data).__name__}")

    # Get field info
    fields = dataclasses.fields(cls)
    field_map = {f.name: f for f in fields}

    # Check for unknown keys
    for key in data:
        if key not in field_map:
            raise LoadError(f"{path}.{key}", f"unknown key '{key}'")

    # Build the instance
    kwargs = {}
    for field in fields:
        name = field.name
        if name in data:
            value = data[name]
            field_path = f"{path}.{name}"
            try:
                kwargs[name] = _validate_type(value, hints.get(name, field.type), field_path)
            except LoadError:
                raise
        else:
            # Missing key
            if field.default is not dataclasses.MISSING:
                kwargs[name] = field.default
            elif field.default_factory is not dataclasses.MISSING:
                kwargs[name] = field.default_factory()
            else:
                raise LoadError(f"{path}.{name}", f"missing required field '{name}'")

    return cls(**kwargs)
